import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create a plane geometry matching the texture's aspect ratio (512x320 → 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);
  const material = new MeshBasicNodeMaterial({
    color: '#e8ecf2', // fallback paper tone
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0);

  // Load the texture asynchronously and apply it to the material
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.map = texture;
    material.needsUpdate = true;
  });

  // No event handlers are required for this static card
  mesh.userData.handlers = {};

  // Cleanup: dispose geometry and material (texture is cached, not owned)
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
